{"query": "
-- Refresh all three materialized views to reflect the updated salary data
REFRESH MATERIALIZED VIEW employees.exec_department_summary;
REFRESH MATERIALIZED VIEW employees.exec_hiring_trends;
REFRESH MATERIALIZED VIEW employees.exec_salary_distribution;

-- Confirm refresh success by querying each view
SELECT 'exec_department_summary' AS view_name, COUNT(*) AS row_count FROM employees.exec_department_summary
UNION ALL
SELECT 'exec_hiring_trends',                   COUNT(*) FROM employees.exec_hiring_trends
UNION ALL
SELECT 'exec_salary_distribution',             COUNT(*) FROM employees.exec_salary_distribution;
"}

